// Inside quotes, \\" and \\\\ stand for a quote and a backslash. When expand is
// set, ${NAME}, ${NAME:-fallback} and $$ are expanded in unquoted and quoted
// values; expanded text is never scanned again.
func parseValue(raw string, expand bool) (string, error) {
	if i := strings.Index(raw, "#"); i >= 0 {
		raw = strings.TrimSpace(raw[:i])
	}
	if strings.HasPrefix(raw, `"`) {
		if len(raw) < 2 || !strings.HasSuffix(raw, `"`) {
			return "", fmt.Errorf("unterminated quoted value")
		}
		return convert(raw[1:len(raw)-1], true, expand)
	}
	return convert(raw, false, expand)
}

// convert applies quote escapes (if unescape) and variable expansion (if
// expand) to s in a single pass.
func convert(s string, unescape, expand bool) (string, error) {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case unescape && c == '\\\\' && i+1 < len(s) && (s[i+1] == '\\\\' || s[i+1] == '"'):
			i++
			b.WriteByte(s[i])
		case expand && c == '$' && i+1 < len(s) && s[i+1] == '$':
			i++
			b.WriteByte('$')
		case expand && c == '$' && i+1 < len(s) && s[i+1] == '{':
			end := strings.IndexByte(s[i+2:], '}')
			if end < 0 {
				return "", fmt.Errorf("unterminated ${ in value")
			}
			ref := s[i+2 : i+2+end]
			i += 2 + end
			name, fallback, hasFallback := strings.Cut(ref, ":-")
			if name == "" {
				return "", fmt.Errorf("empty variable name")
			}
			v, ok := os.LookupEnv(name)
			if hasFallback && v == "" {
				v, ok = fallback, true
			}
			if !ok {
				return "", fmt.Errorf("undefined variable %q", name)
			}
			b.WriteString(v)
		default:
			b.WriteByte(c)
		}
	}
	return b.String(), nil
}
